{"code": "import re,json,collections
h=[r for r in load_history() if r['family']=='xor_classification']
pairs=[]
for r in h:
 q=r['question']; chunks=re.split(r'### Choice ([A-Z])',q); cs=[]
 for i in range(1,len(chunks),2):
  label,t=chunks[i:i+2]
  act=re.search(r'- Activation: (\w+)',t)
  if not act or act.group(1) not in ['relu','leaky_relu']:continue
  fields=[]
  for pat in [r'- Depth: (\d+)',r'- Width: (\d+)',r'- Residual connections: (\w+)',r'- Layer norm per layer: (\[[^\n]+\])',r'- Optimizer: (\w+)',r'- Learning rate: ([^\n]+)',r'- Weight decay: ([^\n]+)',r'- Betas: ([^\n]+)']:
   m=re.search(pat,t);fields.append(m.group(1) if m else None)
  cs.append((label,act.group(1),fields))
 order=re.findall('[A-E]',r['answer'])
 for a in cs:
  for b in cs:
   if a[1]=='relu' and b[1]=='leaky_relu' and a[2]==b[2] and a[0] in order and b[0] in order:pairs.append((r['question_id'],a,b,order.index(a[0])<order.index(b[0])))
print('matched history',len(pairs))
for p in pairs:print(p)
"}

